using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() now uses UTC for seeding timestamps.
        // Use a fixed value instead of DateTime.UtcNow to avoid generating a new
        // migration on every run.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // EF Core 9 Cosmos breaking change #3: Synchronous I/O is no longer supported.
        // All Cosmos queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 Cosmos breaking change #1: The discriminator property is now
        // named "$type" by default instead of "Discriminator".
        // For existing documents that already store "Discriminator", explicitly
        // configure the old property name to avoid breaking existing data.
        modelBuilder.Entity<Document>().HasDiscriminator<string>("Discriminator");
    }
}

class Document
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Example showing the required async pattern for Cosmos DB queries in EF Core 9.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BREAKING CHANGE FIX: Cosmos provider no longer supports synchronous queries.
    // Before (EF Core 8):  _db.Documents.ToList()
    // After  (EF Core 9):  await _db.Documents.ToListAsync()
    public async Task<List<Document>> GetDocumentsAsync()
    {
        return await _db.Documents.ToListAsync();
    }
}

